 private Entity CombinedPrefab(Entity source,Entity prefab){var approach=World.GetExistingSystemManaged<ApproachSignalSystem>();if(approach?.IsTurnOnly(source)??false)return approach.CombinedTarget(source);var target=World.GetExistingSystemManaged<ApproachSignalSystem>()?.CombinedTarget(source)??Entity.Null;if(target!=Entity.Null)return target;if(approach?.ExpectsCustom(source)??false)return Entity.Null;
