 int vehicle=(int)EntityManager.GetComponentData<TrafficLightData>(prefab).m_Type&3;foreach(var name in SourceNames.All)if(name.StartsWith(theme)&&Catalog.Entries.TryGetValue(name,out var e)&&EntityManager.HasComponent<TrafficLightData>(e)&&EntityManager.HasComponent<ObjectData>(e)){int type=(int)EntityManager.GetComponentData<TrafficLightData>(e).m_Type;if((type&3)==vehicle&&(type&12)!=0&&EntityManager.GetComponentData<ObjectData>(e).m_Archetype.Valid)return e;}return Entity.Null;
 }
 private bool TryPedestrianAnchor(Entity owner,Entity source,float3 origin,float2 direction,float3 desired,RoadSurface roads,HashSet<Entity> claimed,out Entity pedestrian,out float3 point,Entity destination=default,System.Text.StringBuilder report=null){pedestrian=Entity.Null;point=origin;float best=float.MaxValue;int candidateMask=0;bool ambiguous=false;var sourceState=EntityManager.GetComponentData<TrafficLight>(source);
 foreach(var item in EntityManager.GetBuffer<Game.Objects.SubObject>(owner,true)){var e=item.m_SubObject;if(e==source||claimed.Contains(e)||(World.GetExistingSystemManaged<ApproachSignalSystem>()?.ClaimsPedestrian(e)??false)||!Live(e)||EntityManager.HasComponent<Temp>(e)||!EntityManager.HasComponent<TrafficLight>(e)||!EntityManager.HasComponent<Transform>(e)||!EntityManager.HasComponent<PrefabRef>(e))continue;var p=EntityManager.GetComponentData<PrefabRef>(e).m_Prefab;if(!EntityManager.HasComponent<TrafficLightData>(p)||((int)EntityManager.GetComponentData<TrafficLightData>(p).m_Type&3)!=0)continue;var state=EntityManager.GetComponentData<TrafficLight>(e);if(state.m_GroupMask1==0||state.m_GroupMask0!=0||(sourceState.m_GroupMask1!=0&&(sourceState.m_GroupMask1&state.m_GroupMask1)==0))continue;var pos=EntityManager.GetComponentData<Transform>(e).m_Position;if(!(destination!=Entity.Null?OnDestinationSide(owner,destination,direction,pos):OnDrivingSide(owner,origin,direction,pos)))continue;var delta=pos-origin;float forward=math.dot(delta.xz,direction);float side=delta.x*direction.y-delta.z*direction.x;float distance=math.distancesq(pos.xz,desired.xz);if(!CombinedSignalRules.Anchor(forward,side,delta.y,distance))continue;if(!PedestrianMergeGeometry.SameCrosswalkEnd(EntityManager,owner,desired,pos,state.m_GroupMask1,36f)){report?.AppendLine("MERGE reject crossing end pedestrian="+e+" distance="+math.sqrt(distance));continue;}if(!ClearRoad(pos,roads,true)){report?.AppendLine("MERGE reject road clearance pedestrian="+e);continue;}
 if(candidateMask!=0&&candidateMask!=state.m_GroupMask1)ambiguous=true;candidateMask=state.m_GroupMask1;float score=distance+side*side;if(score<best){best=score;pedestrian=e;point=pos;}}
 if(ambiguous){pedestrian=Entity.Null;point=origin;report?.AppendLine("MERGE ambiguous pedestrian groups");}report?.AppendLine("MERGE selected="+pedestrian+" anchor="+point);return pedestrian!=Entity.Null;
 }
 private TrafficLight DisplayState(Entity source,Entity pedestrian,bool manual){if(manual){var display=World.GetExistingSystemManaged<ApproachSignalSystem>().DisplayFor(source);if(Live(display)&&EntityManager.HasComponent<TrafficLight>(display))return EntityManager.GetComponentData<TrafficLight>(display);return EntityManager.GetComponentData<TrafficLight>(source);}var state=EntityManager.GetComponentData<TrafficLight>(source);return pedestrian==Entity.Null?FarVehicleRules.VehicleState(state):CombinedSignalRules.Merge(state,EntityManager.GetComponentData<TrafficLight>(pedestrian));}
